+// SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
+// SPDX-License-Identifier: Apache-2.0
+//
+// The flat C ABI (include/cudnn_frontend/experimental/sm120_aot_attention_abi.h) over the exported FROST prefill /
+// combine objects and the quantized-KV decode kernels. Dispatch data (variants, selection tables) is generated by
+// aot/sm120/build.py into aot_registry.inc.
+
+#include "cudnn_frontend/experimental/sm120_aot_attention_abi.h"
+#include "decode_q8_q4.h"
+
+#include <algorithm>
+#include <cmath>
+#include <cstdio>
+#include <cstring>
+#include <mutex>
+#include <new>
+#include <string>
+#include <vector>
+
+namespace {
+
+struct KnobSet {
+    int32_t pack_gqa, sched, split, tile_m, tile_n;
+};
+
+struct ClassInfo {
+    int d, causal, window_left, sink, n_variants;
+};
+
+struct PrefillLaunch {
+    void *q, *k, *v, *o, *lse;
+    const float* sinks;
+    const int32_t* problem;                                    // b, h_q, h_kv, s_q, s_kv
+    const int64_t *q_stride, *k_stride, *v_stride, *o_stride;  // elements {batch, seq, head}
+    float scale_log2;
+    cudaStream_t stream;
+};
+
+struct CombineLaunch {
+    void *o_partial, *lse_partial, *o;
+    const float* sinks;
+    const int32_t* problem;  // b, h_q, s_q, d
+    int32_t n_splits;
+    const int64_t* o_stride;    // elements {batch, seq, head, 1}
+    const int64_t* lse_stride;  // unused: no LSE output
+    cudaStream_t stream;
+};
+
+struct Variant {
+    const char* name;
+    int dtype;      // 0 = f16, 1 = bf16
+    int cls;        // prefill: class position; combine: has sink
+    KnobSet knobs;  // prefill only
+    void (*load)();
+    int32_t (*launch)(const PrefillLaunch&);
+    int32_t (*launch_combine)(const CombineLaunch&);
+    std::once_flag once;
+    cudaError_t load_error;
+};
+
+}  // namespace
+
+// The generated module loaders report CUDA errors through this macro; collect them as a status instead of printing.
+static thread_local cudaError_t g_load_error = cudaSuccess;
+#define CUTE_DSL_CUDA_ERROR_CHECK(err)            \
+    do {                                          \
+        cudaError_t e_ = (err);                   \
+        if (e_ != cudaSuccess) g_load_error = e_; \
+    } while (0)
+
+// The DSL-generated wrappers take a module argument they do not read.
+#pragma GCC diagnostic push
+#pragma GCC diagnostic ignored "-Wunused-parameter"
+#include "aot_registry.inc"
+#pragma GCC diagnostic pop
+
+struct cudnn_fe_aot_sdpa_plan_s {
+    cudnn_fe_aot_sdpa_desc_t desc;
+    bool quantized;
+    int dtype, cls, base;
+    int fixed;                    // >= 0: the pinned g_prefill index; -1: the selection table
+    const uint8_t* table[kNumG];  // per G (1..8, then G > 8) for the device's SM count
+    int combine;                  // g_combine index: (dtype, sink)
+};
+
+namespace {
+
+thread_local std::string g_last_error;
+
+cudnn_fe_aot_status_t
+fail(cudnn_fe_aot_status_t s, std::string msg) {
+    g_last_error = std::move(msg);
+    return s;
+}
+
+constexpr size_t kAlign = 256;
+size_t
+align_up(size_t x) {
+    return (x + kAlign - 1) / kAlign * kAlign;
+}
+
+// Caller structs may be older (shorter) than this build's; fields past their struct_size read as zero.
+template <class T>
+bool
+read_struct(const T* in, T* out, size_t min_size) {
+    if (!in || in->struct_size < min_size) return false;
+    if (in->struct_size >= sizeof(T)) {
+        std::memcpy(out, in, sizeof(T));
+    } else {
+        std::memset(out, 0, sizeof(T));
+        std::memcpy(out, in, in->struct_size);
+    }
+    return true;
+}
+
+int
+dtype_index(int32_t dt) {
+    return dt == CUDNN_FE_AOT_DTYPE_F16 ? 0 : dt == CUDNN_FE_AOT_DTYPE_BF16 ? 1 : -1;
+}
+
+int
+bucket(int64_t x, int n) {
+    int b = 0;
+    while (b + 1 < n && (int64_t(1) << b) < x) ++b;
+    return b;
+}
+
+int
+g_index(int32_t g) {
+    return g <= 8 ? g - 1 : kNumG - 1;
+}
+
+int
+find_class(const cudnn_fe_aot_sdpa_desc_t& d) {
+    const int causal = d.mask == CUDNN_FE_AOT_MASK_CAUSAL;
+    for (int i = 0; i < kNumClasses; ++i) {
+        const ClassInfo& c = kClasses[i];
+        if (c.d == d.head_dim && c.causal == causal && c.window_left == d.window_left && c.sink == (d.has_sinks != 0))
+            return i;
+    }
+    return -1;
+}
+
+std::string
+desc_string(const cudnn_fe_aot_sdpa_desc_t& d) {
+    char buf[192];
+    std::snprintf(buf,
+                  sizeof(buf),
+                  "head_dim=%d q/kv/o dtype=%d/%d/%d mask=%d window_left=%d sinks=%d gqa_ratio=%d",
+                  d.head_dim,
+                  d.q_dtype,
+                  d.kv_dtype,
+                  d.o_dtype,
+                  d.mask,
+                  d.window_left,
+                  d.has_sinks,
+                  d.gqa_ratio);
+    return buf;
+}
+
+cudnn_fe_aot_status_t
+ensure_loaded(Variant& v) {
+    std::call_once(v.once, [&] {
+        g_load_error = cudaSuccess;
+        v.load();
+        v.load_error = g_load_error;
+    });
+    if (v.load_error != cudaSuccess)
+        return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR,
+                    std::string("loading ") + v.name + ": " + cudaGetErrorString(v.load_error));
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+// The class position and dtype a FROST desc resolves to, or a status.
+cudnn_fe_aot_status_t
+resolve_frost(const cudnn_fe_aot_sdpa_desc_t& d, int* dtype, int* cls) {
+    *dtype = dtype_index(d.kv_dtype);
+    if (*dtype < 0 || d.q_dtype != d.kv_dtype || d.o_dtype != d.kv_dtype)
+        return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED,
+                    "f16/bf16 KV needs q_dtype == kv_dtype == o_dtype: " + desc_string(d));
+    if (d.mask != CUDNN_FE_AOT_MASK_NONE && d.mask != CUDNN_FE_AOT_MASK_CAUSAL)
+        return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED,
+                    "f16/bf16 KV supports mask NONE or CAUSAL (index-based): " + desc_string(d));
+    if (d.window_left < -1 || d.gqa_ratio < 0)
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "window_left must be >= -1 and gqa_ratio >= 0");
+    *cls = find_class(d);
+    if (*cls < 0)
+        return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED, "no prebuilt kernels for this shape class: " + desc_string(d));
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+bool
+knobs_equal(const KnobSet& a, const cudnn_fe_aot_sdpa_knobs_t& b) {
+    return a.pack_gqa == b.pack_gqa && a.sched == b.sched_policy && a.split == b.split_kv && a.tile_m == b.tile_m &&
+           a.tile_n == b.tile_n;
+}
+
+void
+to_public(const KnobSet& k, cudnn_fe_aot_sdpa_knobs_t* out) {
+    out->struct_size  = sizeof(*out);
+    out->pack_gqa     = k.pack_gqa;
+    out->sched_policy = k.sched;
+    out->split_kv     = k.split;
+    out->tile_m       = k.tile_m;
+    out->tile_n       = k.tile_n;
+}
+
+// A class's variant usable at GQA ratio g (0 = unknown: unpacked only).
+bool
+usable(const KnobSet& k, int32_t g) {
+    return k.pack_gqa == 0 || k.pack_gqa == g;
+}
+
+constexpr size_t kArgsV1  = offsetof(cudnn_fe_aot_sdpa_args_t, mask_stride) + sizeof(int64_t) * 2;
+constexpr size_t kDescV1  = offsetof(cudnn_fe_aot_sdpa_desc_t, gqa_ratio) + sizeof(int32_t);
+constexpr size_t kKnobsV1 = offsetof(cudnn_fe_aot_sdpa_knobs_t, tile_n) + sizeof(int32_t);
+
+cudnn_fe_aot_status_t
+check_extents(const cudnn_fe_aot_sdpa_plan_s& p, const cudnn_fe_aot_sdpa_args_t& a) {
+    if (a.b < 1 || a.h_q < 1 || a.h_kv < 1 || a.s_q < 1 || a.s_kv < 1)
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "b, h_q, h_kv, s_q and s_kv must be >= 1");
+    if (a.h_q % a.h_kv) return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "h_q must be a multiple of h_kv");
+    if (p.desc.gqa_ratio && a.h_q != p.desc.gqa_ratio * a.h_kv)
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT,
+                    "h_q / h_kv differs from the plan's gqa_ratio " + std::to_string(p.desc.gqa_ratio));
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+// The g_prefill index execute() launches for these extents.
+int
+pick_variant(const cudnn_fe_aot_sdpa_plan_s& p, const cudnn_fe_aot_sdpa_args_t& a) {
+    if (p.fixed >= 0) return p.fixed;
+    const int g = a.h_q / a.h_kv;
+    const int cell =
+        (bucket(int64_t(a.b) * a.h_kv, kNumUnits) * kNumSq + bucket(a.s_q, kNumSq)) * kNumSkv + bucket(a.s_kv, kNumSkv);
+    return p.base + p.table[g_index(g)][cell];
+}
+
+size_t
+frost_workspace(const Variant& v, const cudnn_fe_aot_sdpa_args_t& a, int d, size_t* o_bytes) {
+    if (v.knobs.split <= 1) return *o_bytes = 0;
+    const size_t rows = size_t(v.knobs.split) * a.b;
+    *o_bytes          = align_up(rows * a.s_q * a.h_q * d * 2);
+    return *o_bytes + align_up(rows * a.h_q * a.s_q * sizeof(float));
+}
+
+cudnn_fe_aot_status_t
+check_frost_operands(const cudnn_fe_aot_sdpa_plan_s& p, const cudnn_fe_aot_sdpa_args_t& a) {
+    const void* ptrs[]   = {a.q, a.k, a.v, a.o};
+    const char* names[]  = {"q", "k", "v", "o"};
+    const int64_t* str[] = {a.q_stride, a.k_stride, a.v_stride, a.o_stride};
+    for (int t = 0; t < 4; ++t) {
+        if (!ptrs[t]) return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, std::string(names[t]) + " is null");
+        if (reinterpret_cast<uintptr_t>(ptrs[t]) % 16)
+            return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, std::string(names[t]) + " must be 16-byte aligned");
+        for (int i = 0; i < 3; ++i)
+            if (str[t][i] < 0 || str[t][i] % 16)
+                return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT,
+                            std::string(names[t]) + "_stride[" + std::to_string(i) +
+                                "] must be a non-negative multiple of 16 bytes");
+    }
+    if (p.desc.has_sinks != (a.sinks != nullptr))
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT,
+                    p.desc.has_sinks ? "the plan has sinks: args.sinks must be set"
+                                     : "args.sinks is set but the plan has no sinks");
+    if (a.sinks && reinterpret_cast<uintptr_t>(a.sinks) % 4)
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "sinks must be 4-byte aligned");
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+// Quantized KV: the decode kernels take ggml-convention byte strides (nb[1..3] = dims 1..3).
+void
+to_decode(const cudnn_fe_aot_sdpa_plan_s& p, const cudnn_fe_aot_sdpa_args_t& a, cudnn_fe_aot_sm120_decode_params_t* d) {
+    std::memset(d, 0, sizeof(*d));
+    d->head_dim  = p.desc.head_dim;
+    d->n_q       = a.s_q;
+    d->n_head    = a.h_q;
+    d->n_head_kv = a.h_kv;
+    d->n_kv      = a.s_kv;
+    d->n_seq     = a.b;
+    d->q         = static_cast<const float*>(a.q);
+    d->q_nb[0] = 4, d->q_nb[1] = a.q_stride[1], d->q_nb[2] = a.q_stride[2], d->q_nb[3] = a.q_stride[0];
+    d->kv_type          = p.desc.kv_dtype == CUDNN_FE_AOT_DTYPE_Q8_0 ? CUDNN_FE_AOT_SM120_DECODE_KV_Q8_0
+                                                                     : CUDNN_FE_AOT_SM120_DECODE_KV_Q4_0;
+    const int64_t block = p.desc.kv_dtype == CUDNN_FE_AOT_DTYPE_Q8_0 ? 34 : 18;
+    d->k = a.k, d->k_nb[0] = block, d->k_nb[1] = a.k_stride[1], d->k_nb[2] = a.k_stride[2], d->k_nb[3] = a.k_stride[0];
+    d->v = a.v, d->v_nb[0] = block, d->v_nb[1] = a.v_stride[1], d->v_nb[2] = a.v_stride[2], d->v_nb[3] = a.v_stride[0];
+    if (p.desc.mask == CUDNN_FE_AOT_MASK_ADDITIVE_F16) {
+        d->mask       = a.mask;
+        d->mask_nb[0] = 2, d->mask_nb[1] = a.mask_stride[1], d->mask_nb[2] = a.mask_stride[1] * a.s_q,
+        d->mask_nb[3] = a.mask_stride[0];
+    }
+    d->o       = static_cast<float*>(a.o);
+    d->o_nb[0] = 4, d->o_nb[1] = a.o_stride[2], d->o_nb[2] = a.o_stride[1], d->o_nb[3] = a.o_stride[0];
+    d->scale = a.scale != 0.f ? a.scale : 1.f / std::sqrt(float(p.desc.head_dim));
+}
+
+cudnn_fe_aot_status_t
+decode_status(cudnn_fe_aot_sm120_decode_status_t s) {
+    if (s == CUDNN_FE_AOT_SM120_DECODE_SUCCESS) return CUDNN_FE_AOT_STATUS_SUCCESS;
+    const char* msg = cudnn_fe_aot_sm120_decode_status_string(s);
+    switch (s) {
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_WORKSPACE_TOO_SMALL:
+            return fail(CUDNN_FE_AOT_STATUS_WORKSPACE_TOO_SMALL, msg);
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_UNSUPPORTED_ARCH:
+            return fail(CUDNN_FE_AOT_STATUS_ARCH_MISMATCH, msg);
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_CUDA:
+            return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, msg);
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_UNSUPPORTED_HEAD_DIM:
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_UNSUPPORTED_KV_TYPE:
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_UNSUPPORTED_N_Q:
+        case CUDNN_FE_AOT_SM120_DECODE_ERROR_UNSUPPORTED_FEATURE:
+            return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED, msg);
+        default:
+            return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, msg);
+    }
+}
+
+cudnn_fe_aot_status_t
+check_device(int device, int* sms) {
+    int major = 0, minor = 0;
+    if (cudaDeviceGetAttribute(&major, cudaDevAttrComputeCapabilityMajor, device) != cudaSuccess ||
+        cudaDeviceGetAttribute(&minor, cudaDevAttrComputeCapabilityMinor, device) != cudaSuccess ||
+        cudaDeviceGetAttribute(sms, cudaDevAttrMultiProcessorCount, device) != cudaSuccess)
+        return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, "querying device " + std::to_string(device) + " failed");
+    if (major != 12 || minor != 0)
+        return fail(CUDNN_FE_AOT_STATUS_ARCH_MISMATCH,
+                    "the kernels are built for sm_120a; device " + std::to_string(device) + " is " +
+                        std::to_string(major) + "." + std::to_string(minor));
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
