+AOT_API cudnn_fe_aot_status_t
+cudnn_fe_aot_sm120_sdpa_plan_create(const cudnn_fe_aot_sdpa_desc_t* desc_in,
+                                    const cudnn_fe_aot_sdpa_knobs_t* knobs_in,
+                                    int device,
+                                    cudnn_fe_aot_sdpa_plan_t** out) {
+    g_last_error.clear();
+    if (!out) return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "plan output pointer is null");
+    *out = nullptr;
+    cudnn_fe_aot_sdpa_desc_t d;
+    if (!read_struct(desc_in, &d, kDescV1))
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "desc is null or desc.struct_size is too small");
+    if (device < 0 && cudaGetDevice(&device) != cudaSuccess)
+        return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, "cudaGetDevice failed");
+    int sms = 0;
+    if (cudnn_fe_aot_status_t s = check_device(device, &sms)) return s;
+
+    cudnn_fe_aot_sdpa_plan_s p{};
+    p.desc      = d;
+    p.fixed     = -1;
+    p.quantized = d.kv_dtype == CUDNN_FE_AOT_DTYPE_Q8_0 || d.kv_dtype == CUDNN_FE_AOT_DTYPE_Q4_0;
+    if (p.quantized) {
+        if (knobs_in) return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "knob sets apply to f16/bf16 KV plans only");
+        if (d.q_dtype != CUDNN_FE_AOT_DTYPE_F32 || d.o_dtype != CUDNN_FE_AOT_DTYPE_F32)
+            return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED, "q8_0/q4_0 KV needs f32 Q and O: " + desc_string(d));
+        if (d.head_dim != 128 && d.head_dim != 256)
+            return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED, "q8_0/q4_0 KV supports head_dim 128 and 256");
+        if (d.mask == CUDNN_FE_AOT_MASK_CAUSAL || d.window_left != -1 || d.has_sinks)
+            return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED,
+                        "q8_0/q4_0 KV supports mask NONE or ADDITIVE_F16, no window and no sinks: " + desc_string(d));
+        if (d.mask != CUDNN_FE_AOT_MASK_NONE && d.mask != CUDNN_FE_AOT_MASK_ADDITIVE_F16)
+            return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "unknown mask " + std::to_string(d.mask));
+    } else {
+        if (cudnn_fe_aot_status_t s = resolve_frost(d, &p.dtype, &p.cls)) return s;
+        p.base      = kClassBase[p.dtype][p.cls];
+        const int n = kClasses[p.cls].n_variants;
+        int sm_i    = 0;
+        for (int i = 1; i < kNumSm; ++i)
+            if (std::abs(kSmCounts[i] - sms) < std::abs(kSmCounts[sm_i] - sms)) sm_i = i;
+        for (int g = 0; g < kNumG; ++g) p.table[g] = kSelect[p.cls][sm_i][g];
+        std::vector<int> need;
+        if (knobs_in) {
+            cudnn_fe_aot_sdpa_knobs_t k;
+            if (!read_struct(knobs_in, &k, kKnobsV1))
+                return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "knobs.struct_size is too small");
+            for (int i = 0; i < n && p.fixed < 0; ++i)
+                if (knobs_equal(g_prefill[p.base + i].knobs, k)) p.fixed = p.base + i;
+            if (p.fixed < 0) {
+                char buf[128];
+                std::snprintf(buf,
+                              sizeof(buf),
+                              "knob set (pack_gqa=%d sched=%d split=%d tile_m=%d tile_n=%d) is not prebuilt for ",
+                              k.pack_gqa,
+                              k.sched_policy,
+                              k.split_kv,
+                              k.tile_m,
+                              k.tile_n);
+                return fail(CUDNN_FE_AOT_STATUS_NOT_SUPPORTED,
+                            buf + desc_string(d) + " (cudnn_fe_aot_sm120_sdpa_get_knob_set lists them)");
+            }
+            if (k.pack_gqa && k.pack_gqa != d.gqa_ratio)
+                return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT,
+                            "a PackGQA knob set needs desc.gqa_ratio == knobs.pack_gqa");
+            need.push_back(p.fixed);
+        } else {
+            std::vector<char> seen(n, 0);
+            for (int g = 0; g < kNumG; ++g) {
+                if (d.gqa_ratio && g != g_index(d.gqa_ratio)) continue;
+                for (int c = 0; c < kNumUnits * kNumSq * kNumSkv; ++c) seen[p.table[g][c]] = 1;
+            }
+            for (int i = 0; i < n; ++i)
+                if (seen[i]) need.push_back(p.base + i);
+        }
+        bool any_split = false;
+        for (int v : need) {
+            if (cudnn_fe_aot_status_t s = ensure_loaded(g_prefill[v])) return s;
+            any_split |= g_prefill[v].knobs.split > 1;
+        }
+        p.combine = p.dtype * 2 + (d.has_sinks ? 1 : 0);
+        if (any_split)
+            if (cudnn_fe_aot_status_t s = ensure_loaded(g_combine[p.combine])) return s;
+    }
+    cudnn_fe_aot_sdpa_plan_s* plan = new (std::nothrow) cudnn_fe_aot_sdpa_plan_s(p);
+    if (!plan) return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, "out of host memory");
+    *out = plan;
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+AOT_API void
+cudnn_fe_aot_sm120_sdpa_plan_destroy(cudnn_fe_aot_sdpa_plan_t* plan) {
+    delete plan;
+}
+
+AOT_API cudnn_fe_aot_status_t
+cudnn_fe_aot_sm120_sdpa_workspace_size(const cudnn_fe_aot_sdpa_plan_t* p,
+                                       const cudnn_fe_aot_sdpa_args_t* args_in,
+                                       size_t* bytes) {
+    g_last_error.clear();
+    cudnn_fe_aot_sdpa_args_t a;
+    if (!p || !bytes || !read_struct(args_in, &a, kArgsV1))
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "plan/args/bytes null or args.struct_size too small");
+    *bytes = 0;
+    if (cudnn_fe_aot_status_t s = check_extents(*p, a)) return s;
+    if (p->quantized) {
+        cudnn_fe_aot_sm120_decode_params_t d;
+        to_decode(*p, a, &d);
+        // The size depends only on extents; stand-in pointers keep the decode validator's null checks quiet.
+        static const int64_t dummy[64] = {};
+        d.q = reinterpret_cast<const float*>(dummy), d.k = dummy, d.v = dummy,
+        d.o = reinterpret_cast<float*>(const_cast<int64_t*>(dummy));
+        if (d.mask) d.mask = dummy;
+        if (cudnn_fe_aot_status_t s = decode_status(cudnn_fe_aot_sm120_decode_check(&d))) return s;
+        *bytes = cudnn_fe_aot_sm120_decode_get_workspace_size(&d);
+        return CUDNN_FE_AOT_STATUS_SUCCESS;
+    }
+    size_t o_bytes;
+    *bytes = frost_workspace(g_prefill[pick_variant(*p, a)], a, p->desc.head_dim, &o_bytes);
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+AOT_API cudnn_fe_aot_status_t
+cudnn_fe_aot_sm120_sdpa_execute(const cudnn_fe_aot_sdpa_plan_t* p,
+                                const cudnn_fe_aot_sdpa_args_t* args_in,
+                                void* workspace,
+                                size_t workspace_size,
+                                cudaStream_t stream) {
+    if (!p || !args_in || args_in->struct_size < kArgsV1)
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "plan/args null or args.struct_size too small");
+    cudnn_fe_aot_sdpa_args_t local;
+    const cudnn_fe_aot_sdpa_args_t* ap = args_in;
+    if (args_in->struct_size < sizeof(local)) {
+        read_struct(args_in, &local, kArgsV1);
+        ap = &local;
+    }
+    const cudnn_fe_aot_sdpa_args_t& a = *ap;
+    if (cudnn_fe_aot_status_t s = check_extents(*p, a)) return s;
+    if (p->quantized) {
+        cudnn_fe_aot_sm120_decode_params_t d;
+        to_decode(*p, a, &d);
+        if (p->desc.mask == CUDNN_FE_AOT_MASK_ADDITIVE_F16 && !a.mask)
+            return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "the plan's ADDITIVE_F16 mask needs args.mask");
+        return decode_status(cudnn_fe_aot_sm120_decode_run(&d, workspace, workspace_size, stream));
+    }
+    if (cudnn_fe_aot_status_t s = check_frost_operands(*p, a)) return s;
+    Variant& v  = g_prefill[pick_variant(*p, a)];
+    const int d = p->desc.head_dim;
+    size_t o_bytes;
+    const size_t need = frost_workspace(v, a, d, &o_bytes);
+    if (need && (!workspace || workspace_size < need || reinterpret_cast<uintptr_t>(workspace) % kAlign))
+        return fail(CUDNN_FE_AOT_STATUS_WORKSPACE_TOO_SMALL,
+                    std::string(v.name) + " needs a 256-byte aligned workspace of " + std::to_string(need) + " bytes");
+
+    const float scale        = a.scale != 0.f ? a.scale : 1.f / std::sqrt(float(d));
+    const int32_t problem[5] = {a.b, a.h_q, a.h_kv, a.s_q, a.s_kv};
+    int64_t qs[3], ks[3], vs[3], os[3];
+    for (int i = 0; i < 3; ++i)
+        qs[i] = a.q_stride[i] / 2, ks[i] = a.k_stride[i] / 2, vs[i] = a.v_stride[i] / 2, os[i] = a.o_stride[i] / 2;
+    PrefillLaunch L{};
+    L.q = const_cast<void*>(a.q), L.k = const_cast<void*>(a.k), L.v = const_cast<void*>(a.v);
+    L.sinks = a.sinks, L.problem = problem, L.q_stride = qs, L.k_stride = ks, L.v_stride = vs;
+    L.scale_log2 = scale * 1.4426950408889634f, L.stream = stream;
+    if (v.knobs.split <= 1) {
+        L.o = a.o, L.o_stride = os;
+        if (int32_t r = v.launch(L))
+            return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR,
+                        std::string(v.name) + ": " + cudaGetErrorString(cudaError_t(r)));
+        return CUDNN_FE_AOT_STATUS_SUCCESS;
+    }
+    // Split-major compact partials: O [split * b, s_q, h_q, d] in the I/O dtype, LSE [split * b, h_q, s_q] fp32.
+    const int64_t hd      = int64_t(a.h_q) * d;
+    const int64_t part[3] = {int64_t(a.s_q) * hd, hd, d};
+    char* ws              = static_cast<char*>(workspace);
+    L.o = ws, L.o_stride = part, L.lse = ws + o_bytes;
+    if (int32_t r = v.launch(L))
+        return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, std::string(v.name) + ": " + cudaGetErrorString(cudaError_t(r)));
+    Variant& c                  = g_combine[p->combine];
+    const int32_t cproblem[4]   = {a.b, a.h_q, a.s_q, d};
+    const int64_t o_stride4[4]  = {os[0], os[1], os[2], 1};
+    const int64_t lse_stride[3] = {0, 0, 0};
+    CombineLaunch C{};
+    C.o_partial = ws, C.lse_partial = ws + o_bytes, C.o = a.o, C.sinks = a.sinks, C.problem = cproblem;
+    C.n_splits = v.knobs.split, C.o_stride = o_stride4, C.lse_stride = lse_stride, C.stream = stream;
+    if (int32_t r = c.launch_combine(C))
+        return fail(CUDNN_FE_AOT_STATUS_CUDA_ERROR, std::string(c.name) + ": " + cudaGetErrorString(cudaError_t(r)));
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+AOT_API cudnn_fe_aot_status_t
+cudnn_fe_aot_sm120_sdpa_query(const cudnn_fe_aot_sdpa_plan_t* p,
+                              const cudnn_fe_aot_sdpa_args_t* args_in,
+                              cudnn_fe_aot_sdpa_knobs_t* knobs,
+                              const char** kernel_name) {
+    g_last_error.clear();
+    cudnn_fe_aot_sdpa_args_t a;
+    if (!p || !read_struct(args_in, &a, kArgsV1))
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "plan/args null or args.struct_size too small");
+    if (cudnn_fe_aot_status_t s = check_extents(*p, a)) return s;
+    if (p->quantized) {
+        static thread_local char buf[192];
+        cudnn_fe_aot_sm120_decode_params_t d;
+        to_decode(*p, a, &d);
+        static const int64_t dummy[64] = {};
+        d.q = reinterpret_cast<const float*>(dummy), d.k = dummy, d.v = dummy,
+        d.o = reinterpret_cast<float*>(const_cast<int64_t*>(dummy));
+        if (d.mask) d.mask = dummy;
+        if (cudnn_fe_aot_status_t s = decode_status(cudnn_fe_aot_sm120_decode_describe(&d, buf, sizeof(buf)))) return s;
+        if (knobs) std::memset(knobs, 0, sizeof(*knobs)), knobs->struct_size = sizeof(*knobs);
+        if (kernel_name) *kernel_name = buf;
+        return CUDNN_FE_AOT_STATUS_SUCCESS;
+    }
+    const Variant& v = g_prefill[pick_variant(*p, a)];
+    if (knobs) to_public(v.knobs, knobs);
+    if (kernel_name) *kernel_name = v.name;
+    return CUDNN_FE_AOT_STATUS_SUCCESS;
+}
+
+AOT_API int32_t
+cudnn_fe_aot_sm120_sdpa_num_knob_sets(const cudnn_fe_aot_sdpa_desc_t* desc_in) {
+    cudnn_fe_aot_sdpa_desc_t d;
+    int dtype, cls;
+    if (!read_struct(desc_in, &d, kDescV1) || resolve_frost(d, &dtype, &cls)) return 0;
+    int n = 0;
+    for (int i = 0; i < kClasses[cls].n_variants; ++i)
+        n += usable(g_prefill[kClassBase[dtype][cls] + i].knobs, d.gqa_ratio);
+    return n;
+}
+
+AOT_API cudnn_fe_aot_status_t
+cudnn_fe_aot_sm120_sdpa_get_knob_set(const cudnn_fe_aot_sdpa_desc_t* desc_in,
+                                     int32_t index,
+                                     cudnn_fe_aot_sdpa_knobs_t* knobs) {
+    g_last_error.clear();
+    cudnn_fe_aot_sdpa_desc_t d;
+    int dtype, cls;
+    if (!knobs || !read_struct(desc_in, &d, kDescV1))
+        return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "desc/knobs null or desc.struct_size too small");
+    if (cudnn_fe_aot_status_t s = resolve_frost(d, &dtype, &cls)) return s;
+    for (int i = 0, n = 0; i < kClasses[cls].n_variants; ++i) {
+        const KnobSet& k = g_prefill[kClassBase[dtype][cls] + i].knobs;
+        if (!usable(k, d.gqa_ratio)) continue;
+        if (n++ == index) {
+            to_public(k, knobs);
+            return CUDNN_FE_AOT_STATUS_SUCCESS;
+        }
+    }
+    return fail(CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT, "knob set index out of range");
+}
+
+AOT_API const char*
+cudnn_fe_aot_sm120_status_string(cudnn_fe_aot_status_t s) {
+    switch (s) {
+        case CUDNN_FE_AOT_STATUS_SUCCESS:
+            return "success";
+        case CUDNN_FE_AOT_STATUS_INVALID_ARGUMENT:
+            return "invalid argument";
+        case CUDNN_FE_AOT_STATUS_NOT_SUPPORTED:
+            return "not supported";
+        case CUDNN_FE_AOT_STATUS_WORKSPACE_TOO_SMALL:
+            return "workspace too small";
+        case CUDNN_FE_AOT_STATUS_ARCH_MISMATCH:
+            return "architecture mismatch";
+        case CUDNN_FE_AOT_STATUS_CUDA_ERROR:
+            return "CUDA error";
+        case CUDNN_FE_AOT_STATUS_LIBRARY_NOT_LOADED:
+            return "library not loaded";
+        case CUDNN_FE_AOT_STATUS_ABI_MISMATCH:
+            return "ABI mismatch";
+    }
+    return "unknown status";
+}
+
+AOT_API const char*
+cudnn_fe_aot_sm120_last_error(void) {
+    return g_last_error.c_str();
+}
